 function bind(){canvas.style.touchAction='pan-y';listen(canvas,'pointerdown',e=>{if(pointer!==null)return;pointer=e.pointerId;lastX=e.clientX;canvas.setPointerCapture?.(pointer);manualUntil=performance.now()+8000;});listen(canvas,'pointermove',e=>{if(e.pointerId!==pointer)return;angle+=(e.clientX-lastX)*.012;lastX=e.clientX;dirty=true;});const release=e=>{if(e.pointerId===pointer)pointer=null;};for(const type of ['pointerup','pointercancel','lostpointercapture'])listen(canvas,type,release);listen(canvas,'webglcontextlost',e=>{e.preventDefault();if(stopped)return;renderer.destroy();renderer=makeFallback(canvas);canvas=renderer.canvas;pointer=null;bind();dirty=true;});}
